#!/usr/bin/env python3
"""Compact operations queue API/UI.  No earthquake science data is stored here."""
from __future__ import annotations

from typing import Any
from agent_queue_webui_v1093 import api_payload as base_payload

TERMINAL = {"complete_pass", "closed_fail", "closed_fail_superseded", "cancelled"}


def dispatch_class(row: dict[str, Any], by_id: dict[str, dict[str, Any]]) -> str:
    status = row.get("status")
    if status == "in_progress": return "running"
    if status == "complete_pass": return "completed"
    if status in {"closed_fail", "closed_fail_superseded", "cancelled"}: return "failed"
    reason = (row.get("blocked_reason") or "").lower()
    if "approval" in reason or "承認" in reason: return "approval-wait"
    deps = row.get("dependencies") or []
    if any(by_id.get(dep, {}).get("status") != "complete_pass" for dep in deps): return "dependency-wait"
    if status == "blocked": return "dependency-wait"
    if row.get("assignee") and status == "queued": return "slot-wait"
    return "ready"


def api_payload() -> dict[str, Any]:
    data = base_payload()
    if not data.get("ok"): return data
    rows = data.get("requirements") or []
    by_id = {r["requirement_id"]: r for r in rows}
    counts = {k: 0 for k in ("total", "running", "ready", "dependency-wait", "slot-wait", "approval-wait", "failed", "completed")}
    counts["total"] = len(rows)
    for row in rows:
        row["dispatch_state"] = dispatch_class(row, by_id)
        counts[row["dispatch_state"]] += 1
    data["dispatch_counts"] = counts
    data["schema"] = "agent-queue-compact-v1097"
    return data


